def recursive_diff(a, b, log=False):
    """
    This function calculates the recursive difference between two objects.

    Args:
    a (object): The first object to compare.
    b (object): The second object to compare.
    log (bool): A boolean indicating whether to log the differences. Defaults to False.

    Returns:
    list: A list of differences between the two objects.
    """
    # Base case: If a and b are equal, return an empty list
    if a == b:
        return []

    # If a and b are of different types, log the difference if log is True
    if type(a) != type(b):
        if log:
            print(f"Difference: {a} and {b} are of different types")
        return [f"{a} and {b} are of different types"]

    # If a and b are lists, recursively calculate the difference
    if isinstance(a, list) and isinstance(b, list):
